css:
.style-spacious {
  --slide-primary: #3B82F6;
  --slide-surface: #FFFFFF;
  --slide-text: #111827;
  --slide-secondary: #8B5CF6;
  --slide-accent: #D97706;
  width: 1080px;
  height: 1080px;
  background-color: var(--slide-surface);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 64px;
  position: relative;
  font-family: 'Open Sans', sans-serif;
  color: var(--slide-text);
  box-sizing: border-box;
}

.style-spacious .hook {
  font-family: 'Montserrat', sans-serif;
  font-size: 80px;
  font-weight: 900;
  line-height: 1.1;
  margin: 0;
  max-width: 90%;
  word-wrap: break-word;
}

.style-spacious .text {
  font-family: 'Open Sans', sans-serif;
  font-size: 50px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  max-width: 85%;
  color: var(--slide-text);
}

.style-spacious .step {
  position: absolute;
  top: 48px;
  right: 48px;
  font-family: 'Montserrat', sans-serif;
  font-size: 160px;
  font-weight: 900;
  color: var(--slide-text);
  opacity: 0.08;
  line-height: 1;
  margin: 0;
}

.style-spacious .brand {
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  font-weight: 600;
  color: var(--slide-text);
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.style-spacious::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.04) 0%, transparent 100%);
  pointer-events: none;
}

.slide-code.style-spacious {
  --slide-primary: #3B82F6;
  --slide-surface: #1F2937;
  --slide-text: #F3F4F6;
  --slide-secondary: #60A5FA;
  background-color: var(--slide-surface);
}

.slide-code.style-spacious .hook {
  color: var(--slide-secondary);
}

.slide-code.style-spacious .text {
  color: #E5E7EB;
}

.slide-code.style-spacious .brand {
  color: var(--slide-secondary);
}

.slide-code.style-spacious .step {
  color: var(--slide-text);
  opacity: 0.12;
}

.slide-code.style-spacious::before {
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.08) 0%, transparent 100%);
}

.slide-insight.style-spacious {
  --slide-primary: #8B5CF6;
  --slide-surface: #0F172A;
  --slide-text: #F8FAFC;
  --slide-secondary: #A78BFA;
  background: linear-gradient(135deg, #0F172A 0%, #1E1B4B 100%);
}

.slide-insight.style-spacious .hook {
  color: var(--slide-secondary);
}

.slide-insight.style-spacious .insight-text {
  font-family: 'Open Sans', sans-serif;
  font-size: 48px;
  font-weight: 500;
  line-height: 1.4;
  color: #F1F5F9;
  margin: 0;
  max-width: 85%;
}

.slide-insight.style-spacious .text {
  color: #E2E8F0;
}

.slide-insight.style-spacious .brand {
  color: var(--slide-secondary);
}

.slide-insight.style-spacious .step {
  color: var(--slide-text);
  opacity: 0.1;
}

.slide-insight.style-spacious::before {
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.12) 0%, transparent 100%);
}

@media (prefers-reduced-motion: reduce) {
  .style-spacious::before {
    animation: none !important;
  }
}

@media (prefers-contrast: more) {
  .style-spacious .step {
    opacity: 0.15;
  }
  .slide-code.style-spacious .step {
    opacity: 0.2;
  }
  .slide-insight.style-spacious .step {
    opacity: 0.15;
  }
}
